    "questionNumber": 126,
    "question": "A water testing laboratory records a 5-day Biochemical Oxygen Demand (BOD5) of 2.5 mg O2/L for sample 'River upstream of city'. What is the correct interpretation of this parameter according to NCERT environmental criteria?",
    "options": {
      "A": "It proves that the water contains zero living bacteria because high BOD instantly sterilizes all aquatic life.",
      "B": "It signifies that dissolved molecular oxygen in the water is 25.0 mg/L, making it super-saturated.",
      "C": "It indicates an inorganic acid spill because BOD only measures sulfuric and hydrochloric acid concentrations.",
      "D": "It indicates that the water sample is Clean, reflecting the amount of oxygen required by aerobic microbes to oxidize dissolved organic contaminants."
    },
