    "correctAnswer": "D",
    "correctOption": "D",
    "correctIndex": 3,
    "explanation": "1. CONCEPT:\nBiochemical Oxygen Demand (BOD) quantification.\n\n2. STEP-BY-STEP SOLUTION:\nBOD measures the rate and volume of oxygen uptake by micro-organisms in a water sample. A BOD of 2.5 mg/L corresponds to Natural unpolluted water and signifies Clean.\n\n3. FINAL ANSWER:\nOption D: It indicates that the water sample is Clean, reflecting the amount of oxygen required by aerobic microbes to oxidize dissolved organic contaminants.\n\n4. WHY OTHER OPTIONS ARE WRONG:\nBOD measures biological oxygen consumption during organic oxidation, not dissolved oxygen saturation or inorganic acids.",
